def toy_step(state, weights):
    if len(state) != 16 or len(weights) != 16:
        raise ValueError("Нужны 16 байт")
    feedback = sum((a * w) % 256
                   for a, w in zip(state, weights)) % 256
    return state[1:] + [feedback]

def toy_transform(state, weights):
    for _ in range(16):
        state = toy_step(state, weights)
    return state
